/**
 * Pixel-exact text: Phaser BitmapText with the Press Start 2P bitmap font generated by tools/gen_font.py (white glyphs
 * tinted to palette colours). No browser anti-aliasing, so text stays crisp at every integer device scale. Characters
 * the font does not cover render as '?'. Text is only ever set through these objects (never innerHTML).
 */
import Phaser from 'phaser';
import fontPng from '../../public/fonts/px8.png?url';
import fontXml from '../../public/fonts/px8.xml?url';

export const FONT_KEY = 'px8';
export type UIText = Phaser.GameObjects.BitmapText;

export function preloadFont(scene: Phaser.Scene): void {
  if (!scene.cache.bitmapFont.exists(FONT_KEY)) scene.load.bitmapFont(FONT_KEY, fontPng, fontXml);
}

const hex = (c: string): number => parseInt(c.replace('#', ''), 16);

/** Replace characters missing from the font with '?' (the font covers Latin, Greek and Cyrillic). */
export function fontSafe(scene: Phaser.Scene, s: string): string {
  const chars = scene.cache.bitmapFont.get(FONT_KEY)?.data?.chars as Record<number, unknown> | undefined;
  if (!chars) return s;
  let out = '';
  for (const ch of s) out += ch === '\n' || chars[ch.codePointAt(0) ?? 0] ? ch : '?';
  return out;
}

export interface TextOpts {
  size?: 8 | 16;
  color?: string;
  align?: 'left' | 'center';
  lineSpacing?: number;
}

export function addText(scene: Phaser.Scene, x: number, y: number, s: string, o: TextOpts = {}): UIText {
  const t = scene.add.bitmapText(Math.round(x), Math.round(y), FONT_KEY, fontSafe(scene, s), o.size ?? 8);
  t.setTint(hex(o.color ?? '#d9d2c0'));
  if (o.align === 'center') t.setCenterAlign();
  if (o.lineSpacing) t.setLineSpacing(o.lineSpacing);
  return t;
}

export function setTextColor(t: UIText, color: string): UIText {
  return t.setTint(hex(color));
}

export function setTextValue(t: UIText, s: string): UIText {
  return t.setText(fontSafe(t.scene, s));
}

/**
 * Pixel-aligned origin: centring an odd-width text at origin 0.5 would put it on a half pixel; snap the top-left corner
 * to whole pixels instead (call after setText when the origin is not 0).
 */
export function snap(t: UIText): UIText {
  const w = t.width;
  const h = t.height;
  t.setDisplayOrigin(Math.round(w * t.originX), Math.round(h * t.originY));
  return t;
}
